impl Specification {
    /// The activation lemmas and the three recursive segment lemmas.
    ///
    /// Staged AFTER `add_eval_ir_activation`: the segment lemmas name
    /// `ir_steps_add` (from `add_eval_ir_steps`) and `ir_frames_tail` /
    /// `ir_config_frames` (from `add_eval_ir_activation`). Registered any
    /// earlier, the missing head surfaces as a bogus ARITY error rather than
    /// an unknown identifier — see `add_eval_ir_lzb_steps`.
    ///
    /// # Errors
    /// Returns `SpecError` if any declaration fails to elaborate or
    /// kernel-check.
    pub(super) fn add_eval_ir_lzb_activation(&mut self) -> Result<(), SpecError> {
        self.add_recursive_def(SRC_IR_LZB_MACH0, "ir_lzb_mach0: one activation of the MINTED Level::is_zero body -- func id 0, entry block 0, its single ptr parameter bound at SSA id 0. Everything the caller owns stays universally quantified: the heap, the next-address counter, the call's result ids and the whole frame stack beneath. DerivedProved, zero axiom_deps.")?;
        self.add_recursive_def(SRC_IR_LZB_DMACH, "ir_lzb_dmach: one activation of the AUTHORED deref model -- func id 1, the id the minted body's three `call 1` sites name. Same frame-generic shape as ir_lzb_mach0. DerivedProved, zero axiom_deps.")?;
        self.add_recursive_def(SRC_IR_LZB_AFTER_LOAD, "ir_lzb_after_load: the configuration one step in, with the heap lookup exposed SYNTACTICALLY so a representation hypothesis can rewrite it. The load binds SSA id 3 -- the minted b0's `%3 = load enum.2, ptr %0` -- where the hand model bound 1. DerivedProved, zero axiom_deps.")?;
        self.add_recursive_def(SRC_IR_LZB_DAFTER_LOAD, "ir_lzb_dafter_load: the same, for the deref model, whose load binds SSA id 1. This is where the FIELD-cell hypothesis (a+8 or a+16) enters. DerivedProved, zero axiom_deps.")?;
        self.add_recursive_def(SRC_IR_LZB_STEP_LOAD, "ir_lzb_step_load: ir_step rewritten so the root heap lookup occurs syntactically. Eq.refl -- the content is the SHAPE, not the equality. DerivedProved, zero axiom_deps.")?;
        self.add_recursive_def(SRC_IR_LZB_DSTEP_LOAD, "ir_lzb_dstep_load: the same for the deref model's first instruction. DerivedProved, zero axiom_deps.")?;
        self.add_recursive_def(SRC_IR_LZB_DEREF_ACTIVATION, "ir_lzb_deref_activation: *** THE ASSUMED CALLEE, AS A FRAME-GENERIC LEMMA. *** Seven steps of the deref model, from its frame push to the caller's resumption, for EVERY field address, Arc base, dests list, underlying frame stack, heap and counter. Because dests and rest are abstract, the same lemma discharges all three call sites (b4's, b5's and b7's). Its ONE hypothesis is that the field cell holds a live pointer -- which is exactly what the field-addressed representation relation supplies. What it RETURNS is that pointer plus the Arc header (Nat.add b ir_d16), not the pointer itself: the two extra steps and the offset are the same fact, and they are why the recursive call is entered at the child's real address. DerivedProved, zero axiom_deps.")?;
        self.add_recursive_def(SRC_IR_LZB_ACTIVATION_ZERO, "ir_lzb_activation_zero: Zero is true in SIX steps -- b0's load, extractfield and switch, b1's const and br, and b6's ret. The hand model's leaf cost was five, because it returned from the arm instead of branching to a join. DerivedProved, zero axiom_deps.")?;
        self.add_recursive_def(SRC_IR_LZB_ACTIVATION_SUCC, "ir_lzb_activation_succ: Succ is false in six. A LEAF for is_zero: the child address is bound in the cell and the edge is never followed. DerivedProved, zero axiom_deps.")?;
        self.add_recursive_def(SRC_IR_LZB_ACTIVATION_PARAM, "ir_lzb_activation_param: Param is false in six, for every payload, through the emitted body's own b3 -- a block the hand model did not have. DerivedProved, zero axiom_deps.")?;
        self.add_recursive_def(SRC_IR_LZB_MAX_TRUE_SEG, "ir_lzb_max_true_seg: *** THE DEEPEST MACHINE FACT IN THE CRYSTAL SO FAR. *** Max's recursive edge with the left operand zero: FOUR opaque segments -- deref, self, deref, self -- spliced into one 25 + c1 + c2 step activation. Both children are read, and the answer is the SECOND one's. Neither caller frame is ever written out: the stack each callee sits on is named `ir_frames_tail (ir_config_frames <the k-step config>)`, exact by construction and incapable of drifting from what the machine built. DerivedProved, zero axiom_deps.")?;
        self.add_recursive_def(SRC_IR_LZB_MAX_FALSE_SEG, "ir_lzb_max_false_seg: Max's SHORT-CIRCUIT edge -- the left operand is not zero, so the answer is false and the right operand is never read. It consumes ih1 and NOT ih2; a proof that consumed ih2 here would be describing a machine that does not short-circuit. 19 + c1 steps. DerivedProved, zero axiom_deps.")?;
        self.add_recursive_def(SRC_IR_LZB_IMAX_SEG, "ir_lzb_imax_seg: IMax, reached through the switch DEFAULT edge to b5, which geps to offset 16 ONLY. The first operand is bound in the cell and NEVER READ -- the impredicative collapse -- so this arm consumes only the second child's hypothesis. 14 + c2 steps. DerivedProved, zero axiom_deps.")?;
        Ok(())
    }
}
